-- =============================================================================
-- 09_live_views.sql -- the live game state in the shape of the recorded st_* tables
--
-- The hybrid renderer (06_hybrid.sql) reads st_<table> WHERE tic = :tic. The live
-- variant doom_hybrid_live (generated by client/setup_game.py from 06_hybrid.sql by
-- renaming st_<table> -> lv_<table>) reads these views instead; they present the
-- g_* tables of the running game as tic -1, with REAL columns widened to
-- BINARY_DOUBLE exactly as the recording stores CedarDB's float4 values. Nothing is
-- copied per tic: a frame reads the game tables directly, under Oracle's read
-- consistency.
-- Units are separated by '/' lines (client/setup_game.py).
-- =============================================================================
CREATE OR REPLACE VIEW lv_sectors AS
SELECT -1 AS tic, id, map_id, floor_height, ceil_height, spawn_floor_height, spawn_ceil_height, spawn_floor_tex,
       spawn_light_level, floor_tex, ceil_tex, light_level, special, tag
  FROM g_sectors
/
CREATE OR REPLACE VIEW lv_things AS
SELECT -1 AS tic, id, map_id, TO_BINARY_DOUBLE(x) AS x, TO_BINARY_DOUBLE(y) AS y, TO_BINARY_DOUBLE(z) AS z,
       TO_BINARY_DOUBLE(angle) AS angle, spawn_x, spawn_y, spawn_angle,
       TO_BINARY_DOUBLE(mom_x) AS mom_x, TO_BINARY_DOUBLE(mom_y) AS mom_y, type, flags
  FROM g_things
/
CREATE OR REPLACE VIEW lv_render_things AS
SELECT -1 AS tic, map_id, thing_id, sector_id, spawn_sector_id, sprite, frame, fullbright, spawn_ceiling, thing_height
  FROM g_render_things
/
CREATE OR REPLACE VIEW lv_player_state AS
SELECT -1 AS tic, map_id, player_thing_id, health, alive, level_tics,
       TO_BINARY_DOUBLE(previous_x) AS previous_x, TO_BINARY_DOUBLE(previous_y) AS previous_y,
       TO_BINARY_DOUBLE(position_x) AS position_x, TO_BINARY_DOUBLE(position_y) AS position_y,
       TO_BINARY_DOUBLE(base_z) AS base_z, TO_BINARY_DOUBLE(view_z) AS view_z,
       TO_BINARY_DOUBLE(view_angle) AS view_angle, TO_BINARY_DOUBLE(momentum_x) AS momentum_x,
       TO_BINARY_DOUBLE(momentum_y) AS momentum_y, TO_BINARY_DOUBLE(bob_strength) AS bob_strength,
       TO_BINARY_DOUBLE(previous_view_z) AS previous_view_z,
       TO_BINARY_DOUBLE(previous_view_angle) AS previous_view_angle,
       sector_id, pain_face_tics, armor, armor_class, backpack, ammo_bullets, ammo_shells, ammo_rockets, ammo_cells,
       key_blue, key_yellow, key_red, radsuit_tics, invis_tics, TO_BINARY_DOUBLE(momentum_z) AS momentum_z,
       damage_count, bonus_count, light_amp_tics, power_map, god_mode, noclip, invuln_tics, berserk,
       message, message_tics, frags, death_tics, killer_id, sprite_frame
  FROM g_player_state
/
CREATE OR REPLACE VIEW lv_player_weapons AS
SELECT -1 AS tic, map_id, player_thing_id, current_weapon, pending_weapon, state, seq_index, tics, flash_seq_index,
       flash_tics, TO_BINARY_DOUBLE(sx) AS sx, TO_BINARY_DOUBLE(sy) AS sy, shot_serial, fired_this_tick
  FROM g_player_weapons
/
CREATE OR REPLACE VIEW lv_player_weapon_owned AS
SELECT -1 AS tic, map_id, player_thing_id, weapon_id FROM g_player_weapon_owned
/
CREATE OR REPLACE VIEW lv_monster_ai AS
SELECT -1 AS tic, map_id, thing_id, state, state_tics, seq_index, sector_id, attack_cooldown, fired_this_tick,
       target_thing_id, charge_tics, movedir, movecount
  FROM g_monster_ai
/
CREATE OR REPLACE VIEW lv_thing_health AS
SELECT -1 AS tic, map_id, thing_id, health, max_health, alive FROM g_thing_health
/
CREATE OR REPLACE VIEW lv_world_effects AS
SELECT -1 AS tic, map_id, effect_id, effect_type, TO_BINARY_DOUBLE(x) AS x, TO_BINARY_DOUBLE(y) AS y,
       TO_BINARY_DOUBLE(z) AS z, sector_id, age
  FROM g_world_effects
/
CREATE OR REPLACE VIEW lv_monster_projectiles AS
SELECT -1 AS tic, map_id, projectile_id, owner_thing_id, projectile_type,
       TO_BINARY_DOUBLE(x) AS x, TO_BINARY_DOUBLE(y) AS y, TO_BINARY_DOUBLE(z) AS z,
       TO_BINARY_DOUBLE(vx) AS vx, TO_BINARY_DOUBLE(vy) AS vy, TO_BINARY_DOUBLE(vz) AS vz,
       sector_id, state, age, damage, impact_player
  FROM g_monster_projectiles
/
CREATE OR REPLACE VIEW lv_picked_up_items AS
SELECT -1 AS tic, map_id, thing_id FROM g_picked_up_items
/
CREATE OR REPLACE VIEW lv_sector_light_fx AS
SELECT -1 AS tic, map_id, sector_id, special, base_light, dark_light FROM g_sector_light_fx
/
-- deathmatch slots (empty in single player): the renderer's per-slot colour translation
CREATE OR REPLACE VIEW lv_mp_players AS
SELECT -1 AS tic, map_id, slot, player_thing_id, skill, role_name, TO_BINARY_DOUBLE(pose_x) AS pose_x,
       TO_BINARY_DOUBLE(pose_y) AS pose_y, TO_BINARY_DOUBLE(pose_z) AS pose_z, TO_BINARY_DOUBLE(pose_angle) AS pose_angle,
       last_seen, display_name, claimed_at
  FROM g_mp_players
/
-- switch textures: the segs of lines whose sidedef textures a switch has swapped (only those
-- lines can differ from the map's own textures; an override equal to the original draws the same)
CREATE OR REPLACE VIEW lv_render_seg_tex AS
SELECT -1 AS tic, rs.map_id, rs.seg_id, rs.upper_tex, rs.mid_tex, rs.lower_tex
  FROM g_render_segs rs
 WHERE (rs.map_id, rs.linedef_id) IN (SELECT b.map_id, b.line_id FROM g_line_buttons b)
/
